BEGIN
  UPDATE presupuesto_meta_vendedor
    SET meta_ajustada=p_meta, editada=true, updated_at=now(), updated_por=p_email
  WHERE anio=p_anio AND mes=p_mes AND vendedor_cod=p_vendedor_cod;
  RETURN json_build_object('ok', true);
END;

DECLARE v_nombre text;
BEGIN
  SELECT nombre INTO v_nombre FROM vendedores WHERE cod = p_vendedor_cod LIMIT 1;
  IF v_nombre IS NULL THEN
    SELECT vendedor_nombre INTO v_nombre FROM presupuesto_cobro WHERE anio=p_anio AND mes=p_mes AND vendedor_cod=p_vendedor_cod LIMIT 1;
  END IF;
  v_nombre := COALESCE(v_nombre, p_vendedor_cod);

  UPDATE presupuesto_cobro SET vendedor_cod=p_vendedor_cod, vendedor_nombre=v_nombre
  WHERE anio=p_anio AND mes=p_mes AND cliente_cod=p_cliente_cod;

  PERFORM _recalc_metas(p_anio, p_mes, p_email);
  RETURN json_build_object('ok', true);
END;

