with s as (
  select coalesce(sum(total), 0) as saldo from cartera where contribuyente = p_contribuyente
),
h as (
  select coalesce((select valor::numeric from config_sistema where clave = 'HOLGURA_GARANTIA_PCT'), 0) as pct
)
select s.saldo, s.saldo * (1 + h.pct / 100) from s, h;

DECLARE
  v_carpeta integer := GREATEST(1, p_carpeta_desde);
  v_conteo integer;
BEGIN
  LOOP
    v_conteo := public.fn_contar_garantias_en_carpeta(p_mueble, p_gaveta, v_carpeta);
    EXIT WHEN v_conteo < 25;
    v_carpeta := v_carpeta + 1;
  END LOOP;
  RETURN v_carpeta;
END;

