declare
  v_anio integer := extract(year from (now() at time zone 'America/Costa_Rica'))::integer;
  v_ultimo integer;
begin
  insert into garantias_consecutivo_anual (anio, ultimo)
  values (v_anio, 1)
  on conflict (anio) do update set ultimo = garantias_consecutivo_anual.ultimo + 1
  returning ultimo into v_ultimo;

  return 'PAG-' || v_anio || '-' || lpad(v_ultimo::text, 4, '0');
end;

